const CryptoJS = require('crypto-js');
const message = "The quick brown fox jumps over the lazy dog";
const sig = CryptoJS.HmacSHA256(message, pm.environment.get("secret"));
pm.request.headers.add({ key: "X-Sig-Hex", value: sig.toString() });
pm.request.headers.add({ key: "X-Sig-B64", value: CryptoJS.enc.Base64.stringify(sig) });
